import React, { useState } from "react";
import { ChevronLeft, ChevronRight, RefreshCw, Clock } from "lucide-react";
import { STADIUMS, GRADE_COLORS, TITLE_COLORS } from "../constants.js";
import { GradeBadge } from "./ui.jsx";

const fmtTime = (d) => `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;

export default function RaceSelector({
  date, onDateChange, loading, onReload,
  stadiums, stadium, onStadiumChange,
  races, raceNo, onRaceChange,
  gradeByStadium, titleByRaceNo, nextCloseByStadium,
}) {
  const [closeMode, setCloseMode] = useState(false);
  const label = `${date.getFullYear()}/${String(date.getMonth() + 1).padStart(2, "0")}/${String(date.getDate()).padStart(2, "0")}`;
  const shift = (n) => {
    const d = new Date(date);
    d.setDate(d.getDate() + n);
    onDateChange(d);
  };

  return (
    <>
      <header className="px-4 pt-5 pb-3 sticky top-0 z-20 bg-base/95 backdrop-blur border-b border-line">
        <div className="flex items-center justify-between">
          <h1 className="text-lg font-bold tracking-tight">レース予想ダッシュボード</h1>
          <button onClick={onReload} className="p-1.5 rounded-md hover:bg-panel text-sub2 hover:text-accent transition-colors" aria-label="再読み込み">
            <RefreshCw size={16} className={loading ? "animate-spin" : ""} />
          </button>
        </div>
        <div className="flex items-center justify-center gap-3 mt-3">
          <button onClick={() => shift(-1)} className="p-1.5 rounded-md bg-panel hover:bg-line transition-colors" aria-label="前日"><ChevronLeft size={16} /></button>
          <span className="font-semibold tabular-nums text-sm w-28 text-center">{label}</span>
          <button onClick={() => shift(1)} className="p-1.5 rounded-md bg-panel hover:bg-line transition-colors" aria-label="翌日"><ChevronRight size={16} /></button>
          <button onClick={() => onDateChange(new Date())} className="text-xs text-accent px-2 py-1 rounded-md border border-line hover:bg-panel transition-colors">今日</button>
        </div>
      </header>

      <div className="px-4 mt-3">
        <div className="flex items-center justify-between mb-1.5">
          <div className="text-[11px] text-sub2">開催場 {loading && "（読込中…）"}</div>
          <button
            onClick={() => setCloseMode((m) => !m)}
            className={"flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-semibold border transition-colors " +
              (closeMode ? "bg-accent border-accent text-base" : "bg-panel border-line text-sub2")}
          >
            <Clock size={11} />次回締切
          </button>
        </div>
        <div className="grid grid-cols-6 gap-1.5">
          {STADIUMS.map((s) => {
            const active = stadiums.has(s.no);
            const selected = stadium === s.no;
            const g = gradeByStadium?.[s.no];
            const gc = active && g && g !== "一般" ? GRADE_COLORS[g] : null;
            const close = nextCloseByStadium?.[s.no];
            return (
              <button
                key={s.no}
                disabled={!active}
                onClick={() => onStadiumChange(s.no)}
                style={selected || !gc ? undefined : { background: gc.bg, color: gc.fg, borderColor: gc.bg }}
                className={
                  "flex flex-col items-center justify-center gap-0.5 px-1 py-1.5 rounded-md text-[11px] font-medium border transition-colors leading-none " +
                  (selected ? "bg-accent border-accent text-base"
                    : active ? (gc ? "" : "bg-panel border-line text-ink hover:border-accent")
                      : "bg-transparent border-[#16283A] text-[#4C6478] cursor-not-allowed")
                }
              >
                <span className="truncate w-full text-center">{s.name}</span>
                {closeMode && (
                  <span className="text-[10px] font-bold tabular-nums">
                    {!active ? "―" : close ? fmtTime(close.time) : "終了"}
                  </span>
                )}
              </button>
            );
          })}
        </div>
        {stadium && gradeByStadium?.[stadium] && (
          <div className="flex items-center gap-1.5 mt-2">
            <GradeBadge grade={gradeByStadium[stadium]} />
            <span className="text-[10px] text-sub2">{STADIUMS.find((s) => s.no === stadium)?.name} 開催</span>
          </div>
        )}
      </div>

      {stadium && (
        <div className="px-4 mt-3">
          <div className="grid grid-cols-6 gap-1.5">
            {Array.from({ length: 12 }, (_, i) => i + 1).map((n) => {
              const available = races.includes(n);
              const selected = raceNo === n;
              const t = titleByRaceNo?.[n];
              const key = t ? (String(t).includes("優勝戦") ? "優勝戦" : String(t).includes("準優") ? "準優勝戦" : null) : null;
              const tc = key ? TITLE_COLORS[key] : null;
              return (
                <button
                  key={n}
                  disabled={!available}
                  onClick={() => onRaceChange(n)}
                  style={selected ? undefined : tc ? { borderColor: tc.ring, color: tc.bg } : undefined}
                  className={
                    "py-2 rounded-md text-sm font-semibold border transition-colors tabular-nums " +
                    (selected ? "bg-amber border-amber text-base"
                      : available ? "bg-panel hover:border-accent" + (tc ? "" : " border-line")
                        : "bg-transparent border-[#16283A] text-[#4C6478] cursor-not-allowed")
                  }
                >
                  {n}R
                </button>
              );
            })}
          </div>
          <div className="flex items-center gap-3 mt-1.5 text-[9px] text-weak">
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm" style={{ background: TITLE_COLORS["準優勝戦"].bg }} />準優勝戦</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm" style={{ background: TITLE_COLORS["優勝戦"].bg }} />優勝戦</span>
          </div>
        </div>
      )}
    </>
  );
}
