/**
 * 選手の過去の結果からの自前集計。
 *
 * results v2 には race_title / race_subtitle / race_grade_number や
 * 選手の勝率などの静的情報が含まれない（着順・ST・進入コースのみ）。
 * そのため用途によってソースを使い分けている：
 *
 *   - 今節成績（ProgramsTable）: 着順・進入・STだけで良いので results のみ
 *     （fetchRecentResults）。
 *   - 節間成績・予選順位（RacerStatsModal）: ラウンド名（予選/準優/優勝）や
 *     公式勝率が必要なので、同じ日の programs と results をマージして使う
 *     （fetchRecentSeasonData）。
 *
 * 端末への保存はせず、必要になるたびに BoatraceOpenAPI から直接取得し直す。
 */

import { findRacesArray, findBoatsArray, F, fetchDaily, ymdOf } from "./api.js";
import { API_START, stadiumName, ABNORMAL_FINISH_LABELS } from "../constants.js";

/** 選手詳細を開くたびに遡って取得する日数のデフォルト値。 */
export const DEFAULT_HISTORY_DAYS = 90;

/* ------------------------- 決まり手の正規化 ------------------------- */

const KIMARITE_ALIASES = {
  逃げ: ["逃げ", "nige"],
  差し: ["差し", "sashi"],
  まくり差し: ["まくり差し", "捲り差し", "makurizashi", "makuri-sashi"],
  まくり: ["まくり", "捲り", "makuri"],
  抜き: ["抜き", "nuki"],
  恵まれ: ["恵まれ", "megumare"],
};

export function normalizeKimarite(raw) {
  if (!raw) return null;
  const s = String(raw);
  // まくり差しを「まくり」より先に判定する必要がある
  for (const label of ["まくり差し", "逃げ", "差し", "まくり", "抜き", "恵まれ"]) {
    if (KIMARITE_ALIASES[label].some((a) => s.includes(a))) return label;
  }
  return s;
}

/* ------------------------- 着順コードの解釈 ------------------------- */

/**
 * racer_place_number は 1〜6 が通常の着順。それ以外の値は
 * 失格・欠場等の異常決着を表す独自コードで、正確な対応表（F/L0/L1/K0/K1/
 * S0/S1/S2 のどの数値がどれかという一次資料）が公開されていない。
 */
export function isNormalPlace(place) {
  const n = Number(place);
  return Number.isInteger(n) && n >= 1 && n <= 6;
}

function parseSt(v) {
  if (v === undefined || v === null) return NaN;
  const s = String(v).trim();
  if (/^[FL]/i.test(s)) return NaN; // フライング・出遅れは順位比較の対象外
  const n = Number(s);
  return Number.isFinite(n) ? n : NaN;
}

/**
 * 異常決着の大分類を、着順コードそのものではなく進入コース・STの有無から
 * 推定する（数値コード自体の対応表が非公開なため）。
 *   - 進入コースもSTも無い　　　→ K（事前欠場）
 * 　- STが負の値　　　　　　　　→ F（フライング）
 *   - 進入コースはあるがSTが無い → L（出遅れ）
 *   - 進入・STとも正常に記録　　→ S（それ以外の失格。転覆等も含みうる）
 * 責任の有無（K0/K1, L0/L1, S0/S1/S2 の末尾）まではデータから判別できない。
 */
export function classifyAbnormalFinish(b) {
  if (isNormalPlace(F.place(b))) return null;
  const course = F.courseNo(b);
  const stRaw = F.st(b);
  const st = Number(stRaw);
  const hasSt = stRaw !== undefined && stRaw !== null && Number.isFinite(st);

  if (course === undefined && !hasSt) return "K";
  if (hasSt && st < 0) return "F";
  if (course !== undefined && !hasSt) return "L";
  return "S";
}

/* ------------------------- 取得（端末には保存しない） ------------------------- */

export function addDays(d, n) {
  const nd = new Date(d);
  nd.setDate(nd.getDate() + n);
  return nd;
}

function buildDateList(days, { fromDate, includeFromDate = false } = {}) {
  const base = fromDate ?? new Date();
  const start = includeFromDate ? 0 : 1;
  const dates = [];
  for (let i = start; i < start + days; i++) {
    const d = addDays(base, -i);
    if (d < API_START) break;
    dates.push(d);
  }
  return dates;
}

/**
 * 過去 days 日分の結果(results)を BoatraceOpenAPI から直接取得して、
 * フラットな配列 [{ymd, race}, ...] にして返す。保存はせず、呼び出す
 * たびに毎回ネットワークから取り直す。非開催日・未確定日は 404 に
 * なるので黙って読み飛ばす。concurrency 件ずつ並列取得する。
 *
 * fromDate を指定すると「実際の今日」ではなく、その日を基準に
 * 過去 days 日分を取得する（アプリ側で過去日付を閲覧中の場合に使う）。
 * includeFromDate: true で fromDate 当日分も含める。
 */
export async function fetchRecentResults(
  days = DEFAULT_HISTORY_DAYS,
  { onProgress, signal, concurrency = 8, fromDate, includeFromDate = false } = {}
) {
  const dates = buildDateList(days, { fromDate, includeFromDate });

  const out = [];
  let done = 0;
  for (let i = 0; i < dates.length; i += concurrency) {
    if (signal?.aborted) break;
    const batch = dates.slice(i, i + concurrency);
    const batchResults = await Promise.all(
      batch.map(async (d) => {
        const ymd = ymdOf(d);
        try {
          const json = await fetchDaily("results", d, { signal });
          return { ymd, json };
        } catch {
          // 404 = 非開催日 or 未確定。無視して続行する
          return { ymd, json: null };
        }
      })
    );
    for (const { ymd, json } of batchResults) {
      if (json) {
        for (const race of findRacesArray(json)) out.push({ ymd, race });
      }
    }
    done += batch.length;
    onProgress?.({ done, total: dates.length });
  }

  out.sort((a, b) => (a.ymd < b.ymd ? -1 : a.ymd > b.ymd ? 1 : 0));
  return out;
}

/** programs のレースと results のレースを、艇番ではなく登録番号でマージする。 */
function mergeRace(program, result) {
  if (!program) return result;
  if (!result) return program;
  const resultBoats = findBoatsArray(result);
  const boatByNo = new Map(resultBoats.map((b) => [String(F.racerNo(b)), b]));
  const boats = findBoatsArray(program).map((b) => {
    const rb = boatByNo.get(String(F.racerNo(b)));
    return rb ? { ...b, ...rb } : b;
  });
  return { ...program, ...result, boats };
}

function mergeDailyRaces(programsJson, resultsJson) {
  const byKey = new Map();
  for (const r of findRacesArray(programsJson)) {
    byKey.set(`${F.stadium(r)}-${F.raceNo(r)}`, { program: r });
  }
  for (const r of findRacesArray(resultsJson)) {
    const key = `${F.stadium(r)}-${F.raceNo(r)}`;
    const entry = byKey.get(key) || {};
    entry.result = r;
    byKey.set(key, entry);
  }
  const out = [];
  for (const { program, result } of byKey.values()) {
    out.push(mergeRace(program, result));
  }
  return out;
}

/**
 * 過去 days 日分の programs + results をマージして取得する。
 * ラウンド名（race_subtitle）・グレード・公式勝率など、results だけ
 * では手に入らない情報が必要な「節間成績」向け。programs / results を
 * 1日ぶんずつ並列取得するため、fetchRecentResults の倍のリクエスト数になる。
 */
export async function fetchRecentSeasonData(
  days = DEFAULT_HISTORY_DAYS,
  { onProgress, signal, concurrency = 6, fromDate, includeFromDate = false } = {}
) {
  const dates = buildDateList(days, { fromDate, includeFromDate });

  const out = [];
  let done = 0;
  for (let i = 0; i < dates.length; i += concurrency) {
    if (signal?.aborted) break;
    const batch = dates.slice(i, i + concurrency);
    const batchResults = await Promise.all(
      batch.map(async (d) => {
        const ymd = ymdOf(d);
        const [programs, results] = await Promise.all([
          fetchDaily("programs", d, { signal }).catch(() => null),
          fetchDaily("results", d, { signal }).catch(() => null),
        ]);
        return { ymd, programs, results };
      })
    );
    for (const { ymd, programs, results } of batchResults) {
      if (!programs && !results) continue;
      for (const race of mergeDailyRaces(programs, results)) out.push({ ymd, race });
    }
    done += batch.length;
    onProgress?.({ done, total: dates.length });
  }

  out.sort((a, b) => (a.ymd < b.ymd ? -1 : a.ymd > b.ymd ? 1 : 0));
  return out;
}

/* ------------------------- 過去10走（同枠） ------------------------- */

/**
 * そのレースの全艇のSTの中で、自分のSTが1番手からどれだけ離れているかを返す。
 * 自分が1番手なら、代わりに2番手との差を負の値で返す
 * （例: 自分0.09・2番手0.12 → -0.03。自分0.12・1番手0.09 → +0.03）。
 */
function stGapFromTop(ownStRaw, race) {
  const own = parseSt(ownStRaw);
  if (!Number.isFinite(own)) return null;
  const others = findBoatsArray(race)
    .map((bb) => parseSt(F.st(bb)))
    .filter(Number.isFinite)
    .sort((a, b) => a - b);
  if (!others.length) return null;
  if (own <= others[0] + 1e-9) {
    const second = others.find((v) => v > others[0] + 1e-9);
    return second === undefined ? null : Number((own - second).toFixed(2));
  }
  return Number((own - others[0]).toFixed(2));
}

export function buildSameCourseHistory(allRaces, racerNo, course, limit = 10) {
  const rows = [];
  for (const { ymd, race } of allRaces) {
    for (const b of findBoatsArray(race)) {
      if (String(F.racerNo(b)) !== String(racerNo)) continue;
      const c = F.courseNo(b) ?? F.lane(b);
      if (Number(c) !== Number(course)) continue;
      rows.push({
        ymd,
        date: `${ymd.slice(4, 6)}/${ymd.slice(6, 8)}`,
        stadiumNo: F.stadium(race),
        stadium: stadiumName(F.stadium(race)),
        raceNo: F.raceNo(race),
        course: Number(c),
        place: F.place(b),
        st: F.st(b),
        stGap: stGapFromTop(F.st(b), race),
        grade: normalizeGrade(F.raceGrade(race), F.raceTitle(race)),
        kimarite: F.place(b) === 1 ? normalizeKimarite(F.kimarite(race)) : null,
        raceRef: race,
      });
    }
  }
  return rows.slice(-limit).reverse();
}

/* ------------------------- 今節成績（全選手ぶん一括） ------------------------- */

function daysBetween(a, b) {
  const toDate = (ymd) => new Date(Number(ymd.slice(0, 4)), Number(ymd.slice(4, 6)) - 1, Number(ymd.slice(6, 8)));
  return Math.abs((toDate(b) - toDate(a)) / 86400000);
}

/**
 * 指定した場・日付までの「今節」（連続開催日のかたまり）を、
 * その節に出走した全選手ぶんまとめて算出する。
 * ProgramsTable で6艇ぶん同時に使うための一括版。
 *
 * 各行の stRank は、同じ（過去の）レース内での自艇のSTの速さの順位
 * （フライング・出遅れは対象外）。
 * excludeRaceNo を渡すと、その回号（＝現在表示中のレース）を結果から除く。
 */
export function buildCurrentMeetAll(allRaces, stadium, uptoYmd, { excludeRaceNo } = {}) {
  const byDate = new Map();
  for (const { ymd, race } of allRaces) {
    if (F.stadium(race) !== Number(stadium)) continue;
    if (ymd > uptoYmd) continue;
    if (!byDate.has(ymd)) byDate.set(ymd, []);
    byDate.get(ymd).push(race);
  }
  const days = [...byDate.keys()].sort();
  if (!days.length) return {};

  // 末尾から辿って、間隔が2日を超えたところで打ち切る＝直近の連続開催ブロック
  let start = days.length - 1;
  for (let i = days.length - 1; i > 0; i--) {
    if (daysBetween(days[i], days[i - 1]) > 2) break;
    start = i - 1;
  }
  const meetDays = days.slice(start);

  const out = {};
  for (const ymd of meetDays) {
    for (const race of byDate.get(ymd)) {
      const raceNo = F.raceNo(race);
      if (ymd === uptoYmd && raceNo === excludeRaceNo) continue;

      const boats = findBoatsArray(race);
      const stEntries = boats
        .map((b) => ({ racerNo: F.racerNo(b), st: parseSt(F.st(b)) }))
        .filter((x) => Number.isFinite(x.st))
        .sort((a, b) => a.st - b.st);

      for (const b of boats) {
        const racerNo = F.racerNo(b);
        if (!racerNo) continue;
        const stVal = parseSt(F.st(b));
        const stRank = Number.isFinite(stVal) ? stEntries.findIndex((x) => x.racerNo === racerNo) + 1 : null;

        out[racerNo] ||= [];
        out[racerNo].push({
          ymd,
          date: `${ymd.slice(4, 6)}/${ymd.slice(6, 8)}`,
          raceNo,
          lane: F.lane(b),
          course: F.courseNo(b) ?? F.lane(b),
          st: F.st(b),
          stRank,
          fieldSize: stEntries.length,
          place: F.place(b),
          abnormalCode: classifyAbnormalFinish(b),
          stadiumNo: Number(stadium),
          raceRef: race,
        });
      }
    }
  }
  return out;
}

/* ------------------------- グレード・シリーズの判定 ------------------------- */

/**
 * オールレディース・ヴィーナスシリーズ・ルーキーシリーズ・マスターズリーグは
 * レース名（イベント名）にしか出てこないため、まずタイトル文字列で判定し、
 * 該当しなければ race_grade_number（1=SG/2=G1/3=G2/4=G3/他=一般）で判定する。
 */
export function normalizeGrade(raw, eventTitle) {
  const t = String(eventTitle || "");
  if (t.includes("オールレディース")) return "オールレディース";
  if (t.includes("ヴィーナス")) return "ヴィーナスシリーズ";
  if (t.includes("ルーキー")) return "ルーキーシリーズ";
  if (t.includes("マスターズ")) return "マスターズリーグ";

  if (raw === undefined || raw === null || raw === "") return "一般";
  const s = String(raw).toUpperCase();
  if (s.includes("SG") || s === "1") return "SG";
  if (s.includes("G1") || s.includes("GI") || s === "2") return "G1";
  if (s.includes("G2") || s.includes("GII") || s === "3") return "G2";
  if (s.includes("G3") || s.includes("GIII") || s === "4") return "G3";
  return "一般";
}

/* ------------------------- 節間成績（過去10節） ------------------------- */

/**
 * 選手の出走履歴を「場が同じで日付が連続するかたまり」に切って節とする。
 * allRaces は fetchRecentSeasonData（programs+results マージ）の結果を渡すこと。
 *
 * 各節の最終結果は、その節でこの選手が出走した最後のレースの
 * race_subtitle で判定する（「優勝戦」「準優」を含むかで判定し、
 * 独自イベント名で判定できない場合は「節内で最後に出走したレース」＝
 * その選手にとっての最終戦とみなす）。
 * 勝率は自前の点数集計ではなく、その最終戦時点の公式全国勝率
 * （racer_national_top_1_percent）をそのまま使う。
 */
export function buildMeetSeasons(allRaces, racerNo) {
  const entries = [];
  for (const { ymd, race } of allRaces) {
    const boats = findBoatsArray(race);
    const b = boats.find((bb) => String(F.racerNo(bb)) === String(racerNo));
    if (!b) continue;
    entries.push({
      ymd,
      raceNo: F.raceNo(race),
      stadium: F.stadium(race),
      eventTitle: F.raceTitle(race) || "",
      subtitle: F.raceSubtitle(race) || "",
      grade: normalizeGrade(F.raceGrade(race), F.raceTitle(race)),
      place: F.place(b),
      natWin: F.natWin(b),
      abnormalCode: classifyAbnormalFinish(b),
    });
  }
  entries.sort((a, b) => (a.ymd === b.ymd ? a.raceNo - b.raceNo : a.ymd < b.ymd ? -1 : 1));

  const groups = [];
  let cur = null;
  for (const e of entries) {
    if (cur && cur.stadium === e.stadium && daysBetween(cur.lastYmd, e.ymd) <= 2) {
      cur.entries.push(e);
      cur.lastYmd = e.ymd;
    } else {
      cur = { stadium: e.stadium, firstYmd: e.ymd, lastYmd: e.ymd, entries: [e] };
      groups.push(cur);
    }
  }

  return groups.map((g) => {
    const last = g.entries[g.entries.length - 1];

    // 到達ラウンドは「最後に出走したレース」ではなく「優勝戦 or 準優勝戦に
    // 出走したかどうか」で決める。オールレディース等の一部大会は、準優勝戦の
    // 後（＝最終戦より後）に、勝ち上がれなかった選手向けの「一般戦」「選抜戦」
    // といった消化レースが別途組まれることがあり、単純に「最後に出走した
    // レース」だけを見ると、実際は準優勝戦まで進んでいたのに予選敗退扱いに
    // なってしまう（実例: 2026/06/16 準優勝戦→翌日06/17 選抜戦に出走したケース）。
    const finalEntry = g.entries.find((e) => {
      const s = String(e.subtitle);
      return s.includes("優勝戦") && !s.includes("準優");
    });
    const semiEntry = g.entries.find((e) => String(e.subtitle).includes("準優"));
    const keyEntry = finalEntry || semiEntry || last;
    const abnormal = !isNormalPlace(keyEntry.place);

    let outcome, outcomeLabel;
    if (abnormal) {
      // 理由（フライング/出遅れ/欠場/失格）は進入コース・STの有無から推定した
      // 大分類。責任の有無（0/1/2）まではデータから判別できないため出さない。
      const code = keyEntry.abnormalCode || "S";
      const reason = ABNORMAL_FINISH_LABELS[code] || "失格";
      outcome = "賞典除外";
      outcomeLabel = finalEntry ? `優勝戦（${reason}）` : semiEntry ? `準優勝戦（${reason}）` : `予選敗退（${reason}）`;
    } else if (finalEntry) {
      outcome = finalEntry.place === 1 ? "優勝" : "優勝戦出走";
      outcomeLabel = finalEntry.place === 1 ? "優勝" : `優勝戦${finalEntry.place}着`;
    } else if (semiEntry) {
      outcome = "準優勝戦敗退";
      outcomeLabel = `準優勝戦${semiEntry.place}着`;
    } else {
      outcome = "予選敗退";
      outcomeLabel = "予選敗退";
    }

    // 勝率は「節の最終日時点の公式勝率」なので、到達ラウンドに関係なく
    // 実際に最後に出走したレース（=最終日）の値を使う。
    const winRate = Number.isFinite(Number(last.natWin)) ? Number(last.natWin) : null;

    return {
      stadium: g.stadium,
      stadiumName: stadiumName(g.stadium),
      grade: g.entries.find((e) => e.grade && e.grade !== "一般")?.grade || last.grade || "一般",
      firstYmd: g.firstYmd,
      lastYmd: g.lastYmd,
      period: `${g.firstYmd.slice(4, 6)}/${g.firstYmd.slice(6, 8)}〜${g.lastYmd.slice(4, 6)}/${g.lastYmd.slice(6, 8)}`,
      shortDate: `${g.lastYmd.slice(4, 6)}/${g.lastYmd.slice(6, 8)}`,
      races: g.entries.length,
      winRate,
      abnormal,
      abnormalCode: abnormal ? (keyEntry.abnormalCode || "S") : null,
      outcome,
      outcomeLabel,
      // 予選順位は同一節の全選手の得点を集計して算出する（下の関数で付与）
      prelimRank: null,
      prelimTotal: null,
    };
  });
}

/**
 * 節の予選順位を算出する。
 * 同じ場・同じ期間に出走した全選手の予選（優勝戦/準優勝戦を除く）得点を
 * 集計してランキング化する。公式の得点率とは細部の規定が異なる参考値。
 * 賞典除外（失格・欠場・転覆等）で最終戦を走れなかった節は算出対象外（"-"）とする。
 */
const PLACE_POINTS = { 1: 10, 2: 8, 3: 6, 4: 4, 5: 2, 6: 1 };

export function attachPrelimRanks(allRaces, seasons, racerNo) {
  return seasons.map((s) => {
    if (s.abnormal) return { ...s, prelimRank: null, prelimTotal: null };

    const scores = {}; // racerNo -> {points, races}
    for (const { ymd, race } of allRaces) {
      if (F.stadium(race) !== s.stadium) continue;
      if (ymd < s.firstYmd || ymd > s.lastYmd) continue;
      const subtitle = String(F.raceSubtitle(race) || "");
      if (subtitle.includes("優勝戦") || subtitle.includes("準優")) continue; // 予選のみ
      for (const b of findBoatsArray(race)) {
        const rn = F.racerNo(b);
        if (!rn || !isNormalPlace(F.place(b))) continue;
        scores[rn] ||= { points: 0, races: 0 };
        scores[rn].points += PLACE_POINTS[F.place(b)] || 0;
        scores[rn].races += 1;
      }
    }
    const ranked = Object.entries(scores)
      .map(([rn, v]) => ({ rn, rate: v.races ? v.points / v.races : 0 }))
      .sort((a, b) => b.rate - a.rate);
    const idx = ranked.findIndex((x) => String(x.rn) === String(racerNo));
    return {
      ...s,
      prelimRank: idx >= 0 ? idx + 1 : null,
      prelimTotal: ranked.length || null,
    };
  });
}

/* ------------------------- 選手詳細モーダル用の取得 ------------------------- */

const SEASON_FIRST_CHUNK_DAYS = 90;
const SEASON_EXTRA_CHUNK_DAYS = 30;
const SEASON_MAX_TOTAL_DAYS = 180; // 90（初回）+ 30x3（追加）で最大180日
const SEASON_TARGET = 10;

/**
 * 過去10節ぶん見つかるまで遡って programs+results を取得し続ける。
 * 初回は90日ぶん、以降は10節に届かない場合のみ30日ずつ追加取得する。
 * 合計180日（対応開始日=API_START に達した場合はそこで）に達したら
 * 打ち切る（新人選手など、遡ってもデータが増えないケースの保険）。
 * excludeMeet を渡すと、現在表示中の（進行中の）節を結果から除外する。
 */
export async function fetchSeasonHistoryForRacer(racerNo, {
  targetCount = SEASON_TARGET,
  firstChunkDays = SEASON_FIRST_CHUNK_DAYS,
  extraChunkDays = SEASON_EXTRA_CHUNK_DAYS,
  maxTotalDays = SEASON_MAX_TOTAL_DAYS,
  signal,
  onProgress,
  excludeMeet,
} = {}) {
  let all = [];
  let seasons = [];
  let cursor = new Date();
  let totalDays = 0;
  let round = 0;

  while (totalDays < maxTotalDays) {
    round++;
    const currentRound = round;
    const chunkDays = Math.min(round === 1 ? firstChunkDays : extraChunkDays, maxTotalDays - totalDays);
    if (chunkDays <= 0 || cursor < API_START) break;

    const chunk = await fetchRecentSeasonData(chunkDays, {
      signal,
      fromDate: cursor,
      includeFromDate: true,
      onProgress: (p) => onProgress?.({ ...p, round: currentRound }),
    });
    all = chunk.concat(all);
    totalDays += chunkDays;

    const seasonsRaw = buildMeetSeasons(all, racerNo);
    const withRanks = attachPrelimRanks(all, seasonsRaw, racerNo);
    seasons = excludeMeet
      ? withRanks.filter((s) => !(s.stadium === Number(excludeMeet.stadium) && s.firstYmd <= excludeMeet.ymd && excludeMeet.ymd <= s.lastYmd))
      : withRanks;

    if (seasons.length >= targetCount) break;
    if (!chunk.length && round > 1) break; // これ以上遡ってもデータが無い

    cursor = addDays(cursor, -chunkDays);
  }

  return { all, seasons };
}
